import React, { useState, useCallback } from 'react';
import { useDropzone } from 'react-dropzone';
import { XMLParser } from 'fast-xml-parser';
import { Upload, FileText, AlertCircle, BookOpen } from 'lucide-react';
import './App.css';

// --- RULEBOOK MAPPING (EPC004-16 2023 v1.2) ---
// These mappings correspond strictly to the "Inter-PSP Payment Dataset (DS-02)"
// and "Confirmation Message (DS-03)" defined in the SCT Inst Rulebook.

const FIELD_MAPPINGS = {
  // DS-02: Inter-PSP Payment (pacs.008)
  'pacs.008': [
    { code: 'AT-D001', label: 'Originator IBAN',         path: 'CdtTrfTxInf.DbtrAcct.Id.IBAN' },
    { code: 'AT-D002', label: 'Originator PSP BIC',      path: 'GrpHdr.InstgAgt.FinInstnId.BICFI' },
    { code: 'AT-C001', label: 'Beneficiary IBAN',        path: 'CdtTrfTxInf.CdtrAcct.Id.IBAN' },
    { code: 'AT-C002', label: 'Beneficiary PSP BIC',     path: 'GrpHdr.InstdAgt.FinInstnId.BICFI' },
    { code: 'AT-E001', label: 'Beneficiary Name',        path: 'CdtTrfTxInf.Cdtr.Nm' }, // Rulebook def: Name of Beneficiary
    { code: 'AT-T001', label: 'Scheme ID',               path: 'CdtTrfTxInf.PmtTpInf.SvcLvl.Cd' }, // Should be "SEPA"
    { code: 'AT-T002', label: 'Amount',                  path: 'CdtTrfTxInf.IntrBkSttlmAmt' },
    { code: 'AT-T051', label: 'Settlement Date',         path: 'CdtTrfTxInf.IntrBkSttlmDt' },
    { code: 'AT-T056', label: 'Timestamp (Time of Receipt)', path: 'GrpHdr.CreDtTm' }
  ],

  // DS-03: Positive Confirmation (pacs.002 ACCP)
  'pacs.002_ACCP': [
    { code: 'AT-D002', label: 'Originator PSP BIC',      path: 'GrpHdr.InstdAgt.FinInstnId.BICFI' },
    { code: 'AT-T014', label: 'Originator Ref (Msg ID)', path: 'OrgnlGrpInfAndSts.OrgnlMsgId' },
    { code: 'AT-T054', label: 'Orig. PSP Tx Ref (E2E)',  path: 'TxInfAndSts.OrgnlEndToEndId' },
    { code: 'AT-T055', label: 'Beneficiary PSP Tx Ref (StsID)', path: 'TxInfAndSts.StsId' }
  ],

  // DS-03: Negative Confirmation (pacs.002 RJCT)
  'pacs.002_RJCT': [
    { code: 'AT-D002', label: 'Originator PSP BIC',      path: 'GrpHdr.InstdAgt.FinInstnId.BICFI' },
    { code: 'AT-T014', label: 'Originator Ref (Msg ID)', path: 'OrgnlGrpInfAndSts.OrgnlMsgId' },
    { code: 'AT-T054', label: 'Orig. PSP Tx Ref (E2E)',  path: 'TxInfAndSts.OrgnlEndToEndId' },
    { code: 'AT-R001', label: 'Type of R Message',       path: 'TxInfAndSts.TxSts' }, // e.g., RJCT
    { code: 'AT-R002', label: 'Initiator Party Type',    path: 'TxInfAndSts.StsRsnInf.Orgtr.Id.OrgId.Othr.Id' }, // Often BANK or specific code
    { code: 'AT-R003', label: 'Initiator Party BIC',     path: 'TxInfAndSts.StsRsnInf.Orgtr.Id.OrgId.BICFI' },
    { code: 'AT-R004', label: 'Reason Code',             path: 'TxInfAndSts.StsRsnInf.Rsn.Cd' }
  ]
};

function App() {
  const [xmlContent, setXmlContent] = useState('');
  const [parsedResult, setParsedResult] = useState(null);
  const [error, setError] = useState(null);

  const parser = new XMLParser({
    ignoreAttributes: false,
    attributeNamePrefix: "@_", 
    removeNsp: true 
  });

  const findRootByCandidates = (obj, candidates) => {
    if (!obj || typeof obj !== 'object') return null;
    for (const key of Object.keys(obj)) {
        if (candidates.some(c => c.toLowerCase() === key.toLowerCase())) return obj[key];
    }
    for (const key in obj) {
      if (Object.prototype.hasOwnProperty.call(obj, key)) {
        const found = findRootByCandidates(obj[key], candidates);
        if (found) return found;
      }
    }
    return null;
  };

  const extractValueByPath = (rootObj, path) => {
    try {
      const keys = path.split('.');
      let current = rootObj;
      for (const key of keys) {
        if (!current) return 'MISSING';
        if (Array.isArray(current)) current = current[0];
        const foundKey = Object.keys(current).find(k => k.toLowerCase() === key.toLowerCase());
        if (foundKey) current = current[foundKey];
        else return 'MISSING';
      }
      if (typeof current === 'object' && current['#text']) return current['#text'];
      if (typeof current === 'object') return JSON.stringify(current).substring(0, 20) + '...';
      return current;
    } catch (e) { return 'ERROR'; }
  };

  const processXML = (xmlString) => {
    try {
      setError(null);
      setParsedResult(null);
      const jsonObj = parser.parse(xmlString);

      let type = 'Unknown';
      let isValid = false;
      let extractedData = [];
      let validationMessage = '';
      let isReject = false;

      const pacs008Roots = ['FIToFICustomerCreditTransfer', 'FIToFICstmrCdtTrf', 'F1ToFICstmerCdtTrf'];
      const pacs002Roots = ['FIToFIPaymentStatusReport', 'FIToFIPmtStsRpt'];

      const sctInstRoot = findRootByCandidates(jsonObj, pacs008Roots);
      const statusRoot = findRootByCandidates(jsonObj, pacs002Roots);

      // LOGIC START
      if (sctInstRoot) {
        type = 'pacs.008 (SCT Inst Instruction)';
        isValid = true;
        validationMessage = "Valid DS-02 Dataset Structure Found";
        extractedData = FIELD_MAPPINGS['pacs.008'].map(f => ({
           ...f, value: extractValueByPath(sctInstRoot, f.path)
        }));
      } 
      else if (statusRoot) {
        const txInfo = statusRoot.TxInfAndSts || statusRoot.TransactionInformationAndStatus;
        const firstTx = Array.isArray(txInfo) ? txInfo[0] : txInfo;
        const status = firstTx?.TxSts || firstTx?.TransactionStatus || 'UNKNOWN';

        if (status === 'RJCT') {
            type = 'pacs.002 (Negative Confirmation)';
            isReject = true;
            isValid = true;
            validationMessage = "DS-03 Negative Confirmation (RJCT)";
            extractedData = FIELD_MAPPINGS['pacs.002_RJCT'].map(f => ({
                ...f, value: extractValueByPath(statusRoot, f.path)
            }));
        } else if (status === 'ACCP') {
            type = 'pacs.002 (Positive Confirmation)';
            isValid = true;
            validationMessage = "DS-03 Positive Confirmation (ACCP)";
            extractedData = FIELD_MAPPINGS['pacs.002_ACCP'].map(f => ({
                ...f, value: extractValueByPath(statusRoot, f.path)
            }));
        } else {
            type = `pacs.002 (Status: ${status})`;
            isValid = false;
            validationMessage = "Status code not recognized (Expected ACCP or RJCT)";
        }
      } 
      else {
          validationMessage = "No valid SCT Inst Root tag found.";
      }

      setParsedResult({ type, isValid, message: validationMessage, data: extractedData, isReject });

    } catch (err) {
      setError("XML Syntax Error: " + err.message);
    }
  };

  const onDrop = useCallback((acceptedFiles) => {
    const file = acceptedFiles[0];
    const reader = new FileReader();
    reader.onload = () => { setXmlContent(reader.result); processXML(reader.result); };
    reader.readAsText(file);
  }, []);

  const { getRootProps, getInputProps } = useDropzone({ onDrop });

  return (
    <div className="container">
      <div className="header">
        <h1>SCT Inst Rulebook Validator</h1>
        <p style={{color: '#666'}}>EPC004-16 2023 v1.2 Compliance Check</p>
      </div>

      <div className="input-methods">
        <div className="card">
            <div {...getRootProps({ className: 'dropzone' })}>
                <input {...getInputProps()} />
                <p>Drag & drop XML file</p>
            </div>
        </div>
        <div className="card">
            <textarea value={xmlContent} onChange={(e) => setXmlContent(e.target.value)} placeholder="Paste XML..." />
            <button className="btn" onClick={() => processXML(xmlContent)}>Validate</button>
        </div>
      </div>

      {error && <div className="card" style={{color: 'red'}}><AlertCircle size={20}/> {error}</div>}

      {parsedResult && !error && (
        <div className="results-area card">
            <div style={{display: 'flex', justifyContent: 'space-between'}}>
                <h2>Analysis Result</h2>
                <span className={`badge ${parsedResult.isReject ? 'badge-error' : 'badge-success'}`}>
                    {parsedResult.type}
                </span>
            </div>
            <p><BookOpen size={16} style={{verticalAlign: 'text-top'}}/> {parsedResult.message}</p>

            {parsedResult.data.length > 0 && (
                <table>
                    <thead>
                        <tr>
                            <th style={{width: '100px'}}>EPC Code</th>
                            <th>Attribute Name</th>
                            <th>Extracted Value</th>
                        </tr>
                    </thead>
                    <tbody>
                        {parsedResult.data.map((r, i) => (
                            <tr key={i}>
                                <td><span className="badge badge-info" style={{fontSize:'0.85em'}}>{r.code}</span></td>
                                <td>
                                    {r.label}
                                </td>
                                <td>
                                    {r.value === 'MISSING' 
                                        ? <span style={{color: '#ff9800', fontWeight: 'bold'}}>MISSING</span> 
                                        : <code style={{color: '#333', fontWeight: 'bold'}}>{r.value}</code>
                                    }
                                </td>
                            </tr>
                        ))}
                    </tbody>
                </table>
            )}
        </div>
      )}
    </div>
  );
}

export default App;
